import assert from 'node:assert/strict';
import {CortexEngine,NODE_COUNT} from './engine.mjs';
assert.equal(new CortexEngine().params.pulseMode,'regional');
const storm=new CortexEngine(65);storm.set({pulseMode:'brainstorm',pulseEnabled:true,pulseRate:.25,pulseJitter:0,pulseStrength:1,coupling:0});storm.advanceEvents(4.5);const burst=storm.drainEvents();assert.ok(burst.length>=14&&burst.length<=16);assert.equal(new Set(burst.map(e=>e.group)).size,burst.length);assert.ok(burst.some(e=>e.group<8)&&burst.some(e=>e.group>=8));assert.ok(burst.every(e=>e.directOnly&&e.source==='brainstorm'&&e.strength>=.75&&e.strength<=1));assert.ok(Math.max(...burst.map(e=>e.time))-4<=.65*.38+1e-8);assert.equal(new Set(burst.map(e=>e.patternId)).size,1);storm.set({pulseEnabled:false});storm.advanceEvents(7);storm.applyDueKicks(7);storm.time=7;storm.measure();assert.equal(storm.pending.length,0);assert.ok(storm.activation.every(x=>x===0));
const rain=new CortexEngine(66);rain.set({pulseMode:'rain',pulseEnabled:true,pulseRate:2,pulseJitter:0,pulseStrength:1,coupling:8,mode:'global'});rain.advanceEvents(.9);const first=rain.drainEvents();assert.equal(first.length,1);rain.advanceEvents(3.1);const drops=[...first,...rain.drainEvents()];assert.equal(drops.length,6);assert.ok(drops.every(e=>e.directOnly&&e.hop===0&&e.source==='rain'&&e.strength>=.25&&e.strength<=.7));assert.ok(new Set(drops.map(e=>e.nodeIndex)).size>3);assert.ok(new Set(drops.map(e=>e.strength)).size>3);assert.equal(rain.pending.length,0);
for(const mode of['brainstorm','rain']){const a=new CortexEngine(71),b=new CortexEngine(71);for(const e of[a,b]){e.set({pulseMode:mode,pulseEnabled:true,pulseRate:12,pulseJitter:1,pulseStrength:1,attack:2,coupling:8,mode:'global'});for(let n=0;n<60;n++){e.advanceEvents((n+1)*.1);assert.ok(e.pending.length<=1024);assert.ok(new Set(e.pending.map(x=>x.wave.id)).size<=64);assert.equal(e.kickStrength.length,NODE_COUNT);}}assert.deepEqual(a.drainEvents(),b.drainEvents());const phases=a.phase.slice();a.time=6;a.set({pulseMode:mode==='rain'?'brainstorm':'rain'});assert.deepEqual(a.phase,phases);assert.equal(a.pending.length,0);assert.ok(a.kickStrength.every(x=>x===0));assert.ok(a.nextPulseAt>6);assert.equal(a.drainEvents().length,0);a.clearActivity();assert.equal(a.pending.length,0);}
const manual=new CortexEngine(79);manual.set({pulseMode:'rain',coupling:2.4});manual.excite(0,1);manual.advanceEvents(.4);assert.ok(manual.drainEvents().some(e=>e.source==='propagation'));
console.log(JSON.stringify({ok:true,regionalDefault:true,stormUniqueRegions:burst.length,stormBothHemispheres:true,stormCouplingIndependent:true,finiteFade:true,rainIsolatedAtHighCoupling:true,rainDrops:6,seededReproducibility:true,pendingCap:1024,waveCap:64,modeSwitchPreservesPhaseClearsArrivals:true,manualRegionalUnchanged:true},null,2));
